window.PMM_NAHJ_TRANSCRIPT_ACCEPT({"group":"sermons","number":198,"source":"خطبه 198.docx","mode":"explicit-parts","parts":["خطبه ۱۹۸\nبخش اول\nمتن:\nترجمه:\nتفسیر:\nکتاب فیض‌الاسلام ۱۸۹\nموضوع: فضیلت اسلام و قرآن\nبرخی از شارحان معتقدند که این خطبه و خطبه ۱۰۶ در واقع یک خطبه بوده‌اند و سیدرضی این بخش را به‌صورت جداگانه آورده است. چند جمله ابتدایی، معجزه سخن حضرت را، هم از نظر الفاظ و هم از نظر معنا و محتوا، نشان می‌دهد. نثر خطبه فخیم و ادیبانه و معانی آن بلند است.\n«یعْلَمُ عَجِیجَ الْوُحُوشِ فِی الْفَلَوَاتِ»\nخدای متعال فریاد و صدای بلند [عَجِیجَ] حیوانات را در فلات‌ها و بیابان‌های پهناور می‌شنود. (هم‌صدای آن‌ها را می‌شنود، هم علت آن را می‌داند و هم قدرت اجابت نیازشان را دارد.) اگر کسی در هر کجای عالم از روی غم ناله سر دهد، خدا آن را می‌شنود، علت آن را می‌داند و قادر است عامل آن را برطرف کند. وقتی خداوند فریاد یک حیوان را می‌شنود و فریادرس اوست، چرا ما تضرع نکنیم و از خدا نخواهیم که فریادرس ما شود؟\nگاهی ما مکلف به مناجات با صدای آرام هستیم و گاهی به مناجات (با صدای بلند) مکلفیم؛ همان‌گونه که جبرئیل در زمان احرام بر پیامبر نازل شد و فرمود:\n«مُرْ أَصْحَابَک بِالْعَجِّ»؛ به اصحابت امر کن تا با فریاد و صدای بلند لبیک بگویند.\nاگر فریاد نزنیم و تضرع نکنیم، از آن حیوانات یک پله عقب‌تریم.\nامام صادق (علیه‌السلام) می‌فرمایند:\n«یا مُیسِّرُ، ادْعُ وَلَا تَقُلْ إِنَّ الْأَمْرَ قَدْ فُرِغَ مِنْهُ، إِنَّ عِنْدَ اللَّهِ عَزَّ وَجَلَّ مَنْزِلَةً لَا تُنَالُ إِلَّا بِمَسْأَلَةٍ، وَلَوْ أَنَّ عَبْدًا سَدَّ فَاهُ وَلَمْ یسْأَلْ لَمْ یعْطَ شَیئًا، فَسَلْ تُعْطَ، یا مُیسِّرُ، إِنَّهُ لَیسَ مِنْ بَابٍ یقْرَعُ إِلَّا یوشِک أَنْ یفْتَحَ لِصَاحِبِهِ»\nای میسر! دعا کن و مگو که کار از کار گذشته است و آنچه مقدر شده، همان خواهد شد (و دعا اثری ندارد). همانا نزد خدای عزوجل منزلت و مقامی وجود دارد که جز با درخواست و مسئلت نمی‌توان به آن رسید. اگر بنده‌ای دهان خود را ببندد و درخواست نکند، چیزی به او داده نمی‌شود. پس درخواست کن تا به تو داده شود. ای میسر! هیچ دری نیست که کوبیده شود، مگر اینکه امید می‌رود به روی کوبنده آن باز شود.\nدعا، تضرع و خواستن از خدا موضوعیت دارد:\nدعا یکی از اسباب حل‌شدن مشکلات است.\nخواستن، شرط رسیدن به‌مراتب بالاست.\nدعا رزق را به‌سوی ما می‌آورد؛ بنابراین، نباید ناامید شد. برای خدا هیچ‌گاه «نشد» وجود ندارد.\n«وَمَعَاصِی الْعِبَادِ فِی الْخَلَوَاتِ»\nخداوند گناهان بندگان را در خلوت می‌داند. توجه به علم خدا در رشد معنوی ما مؤثر است؛ به همین دلیل، در روایات بسیاری بر علم خدا تأکید شده است؛ زیرا کسی که به علم خداوند آگاه باشد، هر طور که بخواهد زندگی نمی‌کند.\nآیه ۱۰۸ سوره نساء:\n«یسْتَخْفُونَ مِنَ النَّاسِ وَلَا یسْتَخْفُونَ مِنَ اللَّهِ وَهُوَ مَعَهُمْ إِذْ یبَیتُونَ مَا لَا یرْضَی مِنَ الْقَوْلِ وَکانَ اللَّهُ بِمَا یعْمَلُونَ مُحِیطًا»؛ آنان خیانت خود را از مردم پنهان می‌کنند، ولی نمی‌توانند آن را از خداوند پنهان دارند؛ درحالی‌که شبانه سخنان ناخشنود کننده خداوند را بر زبان می‌آورند و توطئه‌های پنهانی می‌کنند. خداوند همواره به آنچه انجام می‌دهند، احاطه دارد.\nعده‌ای از خداوند خوفی ندارند، اما از بندگان خدا می‌ترسند.\n«وَاخْتِلَافَ النِّینَانِ فِی الْبِحَارِ الْغَامِرَاتِ»\nخداوند تمام حرکت نهنگ‌ها [النِّینَانِ] را در دریاهای عمیق و پهناور [غَامِرَاتِ] می‌داند. خداوند از کیفیت و کمیت حرکت موجودات، از جمله نهنگ‌ها، آگاه است. محدودیت‌های ما مانع فهم و درک عمیق مسائل می‌شود؛ برخلاف خداوند متعال که از جزئی‌ترین اوصاف، حالات و نیازهای مخلوقاتش آگاه است و می‌تواند نیازهای آن‌ها را اجابت کند.\n«وَتَلَاطُمَ الْمَاءِ بِالرِّیاحِ الْعَاصِفَاتِ»\nخدای متعال از تلاطم امواج دریاها بر اثر تندبادهای درهم‌شکننده [الْعَاصِفَاتِ] آگاه است. علم خداوند نسبت به تک‌تک امواج، هم از نظر کمیت و هم از نظر کیفیت، علت شکل‌گیری آن‌ها و میزان خسارتشان و... احاطه دارد.\n«وَأَشْهَدُ أَنَّ مُحَمَّدًا نَجِیبُ اللَّهِ وَسَفِیرُ وَحْیهِ وَرَسُولُ رَحْمَتِهِ»\nپس از شهادت به علم خداوند، شهادت می‌دهم که محمد (صلی‌الله علیه و آله) برگزیده خدا، سفیر وحی الهی و پیامبر رحمت است. خداوندِ عالمی که بر همه موجودات اشراف دارد، محمد را به پیامبری برگزید و با این کار، به آفرینش همه مخلوقات هدف بخشید. هدف از ارسال پیامبر، دستگیری از ماست. رحمت پیامبر تنها مختص انسان‌ها نیست، بلکه همه موجودات و ملائکه را نیز در برمی‌گیرد؛ ازاین‌رو، او «رَحْمَةً لِلْعَالَمِینَ» است.\n«أَمَّا بَعْدُ، فَإِنِّی أُوصِیکمْ بِتَقْوَی اللَّهِ الَّذِی ابْتَدَأَ خَلْقَکمْ»\nپس از مقدمه‌ای که بیان شد، شما را به رعایت تقوای خدایی توصیه می‌کنم که شما را آفرید.\n«وَإِلَیهِ یکونُ مَعَادُکمْ»\nمتقی باشید؛ زیرا بازگشت شما به‌سوی خداست. تقوا را رعایت کنید، چراکه باید پاسخ‌گوی اعمال خود باشید.\nعلت رعایت تقوا:\n۱. بر اساس قاعده «وجوب شکر منعم»، همه ما موظفیم به‌خاطر نعمت آفرینش از خداوند قدردانی کنیم؛ آفرینشی که زمینه آشنایی ما با علی و اولادش و رسیدن به مدارج بالای معنویت را فراهم کرده است. اگر خداوند ما را نمی‌آفرید، چیزی نبودیم: «لَمْ یکنْ شَیئًا مَذْکورًا». این قدردانی جز با رعایت تقوای الهی محقق نمی‌شود.\n۲. علت دیگر رعایت تقوا، وجود معاد و بازگشت همه مخلوقات به‌سوی خداوند است.\n«وَبِهِ نَجَاحُ طَلِبَتِکمْ»\nرسیدن به خواسته‌ها و موفقیت در آن‌ها، فقط و فقط به سبب اوست. ظاهر کلام چنین است که لفظ «به» باید در پایان جمله بیاید؛ اما برای رساندن مفهوم حصر، در ابتدای جمله آمده است. حضرت می‌فرماید: خدایا، مرا به انسان‌ها واگذار مکن؛ زیرا آن‌ها «مَعْدِنُ الْخَیبَةِ» (معدن ناامیدی) هستند. به تعبیر زین‌العابدین (علیه‌السلام) در دعای ۲۸ صحیفه سجادیه:\n«طَلَبُ الْمُحْتَاجِ إِلَی الْمُحْتَاجِ سَفَهٌ»؛ درخواست‌کردن محتاج از محتاج، عین سفاهت است.\n«وَإِلَیهِ مُنْتَهَی رَغْبَتِکمْ»\nانتهای آرزوی شما باید تنها به‌سوی او باشد. آرزوی ما نباید به دنیا ختم شود، بلکه باید خداوند و اهل‌بیت مقصد نهایی آرزوهایمان باشند.\n«وَنَحْوَهُ قَصْدُ سَبِیلِکمْ»\nراه شما باید به‌سوی خدا منتهی شود. خدا را مقصد خود انتخاب کنید.\n«وَإِلَیهِ مَرَامِی مَفْزَعِکمْ»\nپناهگاه شما باید او باشد. [مَرَامِی مَفْزَعِکمْ] به جایی اشاره دارد که انسان هنگام ترس به آن پناه می‌برد. انسان در حالت فزع و ترس شدید، خود را به پناهگاهی می‌رساند. پناهگاه ما در مشکلات باید آغوش خدا و اهل‌بیت باشد؛ زیرا پناه‌بردن به غیر آنان، بیراهه رفتن است.\nدر زندگی‌نامه امام عسکری (علیه‌السلام) آمده است که یکی از شاعران دربار متوکل عباسی به نام ابو یوسف، پس از مدتی، دیگر جذابیت گذشته را در اشعارش نداشت و بیکار شد. اوضاع مالی‌اش به هم ریخت و در همان زمان، خداوند فرزندی به او داد. او از شدت سختی و برای طلب روزی، به دوستانش در دربار نامه نوشت؛ اما هیچ‌کس به او کمکی نکرد. در این زمان، از شدت فزع و درماندگی در کوچه‌های سامرا قدم می‌زد که از کنار خانه امام عسکری گذشت. در همین هنگام، به ذهنش خطور کرد که از امام درخواست کمک کند؛ اما باز هم این کار را نکرد. هنگامی که قصد بازگشت داشت، درِ خانه حضرت باز شد و غلام ایشان با کیسه‌ای پول به‌سوی او آمد، پول را به او داد و گفت که سیدش می‌فرماید:\n«أَنْفِقْ هَذِهِ عَلَی الْمَوْلُودِ، بَارَک اللَّهُ لَک فِیهِ»؛ این پول را بگیر و خرج فرزندت کن؛ خداوند او را برایت مبارک گرداند.\nبرخلاف پادشاهان و اشخاصی که هنگام سود و منفعت در کنار فرد هستند، اما وقتی او کارایی خود را از دست می‌دهد، از خود می‌رانندش، در مورد خداوند و ائمه، کافی است از کنار آنان عبور کنید تا شما را در آغوش بگیرند و نیازتان را برآورده کنند.\nکافی است یک‌بار «یا الله» بگویید؛ فرقی نمی‌کند در چه زمان و شرایطی باشید. خداوند همان یک‌بار شما را می‌خرد و پناهگاهتان می‌شود. این میزان از لطف، احسان، معنویت و دلربایی، تنها مختص خداوند و ائمه اطهار است.\nآثار تقوا:\n«فَإِنَّ تَقْوَی اللَّهِ دَوَاءُ دَاءِ قُلُوبِکمْ»\n۱. بیماری‌های قلب شما تنها باتقوا درمان می‌شود. بیماری‌های قلبی شامل کبر، نفاق، حسادت، بخل و... است. بیماری‌های روحی، مانند بیماری‌های جسمی، لزوماً با درد نمایان نمی‌شوند؛ همین امر موجب می‌شود که فرد سال‌ها درگیر بیماری‌های روحی باشد، اما از آن‌ها آگاه نشود. درمان این بیماری‌های روحی، تقواست.\n«وَبَصَرُ عَمَی أَفْئِدَتِکمْ»\n۲. تقوا، بصیرت و بینایی قلب‌های شماست. تقوا چشم‌وچراغ قلب است. امام زین‌العابدین (علیه‌السلام) فرمودند:\n«أَلَا إِنَّ لِلْعَبْدِ أَرْبَعَ أَعْینٍ: عَینَانِ یبْصِرُ بِهِمَا أَمْرَ دِینِهِ وَدُنْیاهُ، وَعَینَانِ یبْصِرُ بِهِمَا أَمْرَ آخِرَتِهِ. فَإِذَا أَرَادَ اللَّهُ بِعَبْدٍ خَیرًا فَتَحَ لَهُ الْعَینَینِ اللَّتَینِ فِی قَلْبِهِ فَأَبْصَرَ بِهِمَا الْغَیبَ فِی أَمْرِ آخِرَتِهِ، وَإِذَا أَرَادَ بِهِ غَیرَ ذَلِک تَرَک الْقَلْبَ بِمَا فِیهِ»\nآگاه باشید که بنده چهارچشم دارد؛ با دو چشم، امور دین و دنیای خود را می‌بیند و با دو چشم دیگر، امور آخرتش را. هرگاه خداوند برای بنده‌ای خیر بخواهد، آن دوچشمی را که در قلب اوست می‌گشاید و او با آن‌ها، غیب و امور مربوط به آخرتش را می‌بیند. اما اگر غیر از این را برای او بخواهد، قلب را با همان وضعی که دارد، به حال خود رها می‌کند. طبق فرمایش امام، این دو چشم قلب، نشانه ایمان‌اند؛ اگر گشوده نشوند، یعنی هنوز به آن درجات بالای ایمان نرسیده‌ایم.\nبه تعبیر قرآن در آیه ۸۳ سوره یس:\n«فَسُبْحَانَ الَّذِی بِیدِهِ مَلَکوتُ کلِّ شَیءٍ وَإِلَیهِ تُرْجَعُونَ»؛ هر چیزی ملکوتی دارد که خداوند به آن آگاه است و ما نیز می‌توانیم تااندازه‌ای به آن ملکوت دست پیدا کنیم. هر چیزی ظاهری دارد که همه آن را می‌بینند و باطنی دارد که دیدن آن از عهده همه برنمی‌آید. برای مثال، باران ظاهری دارد که همه آن را می‌بینند؛ اما باطن آن، یعنی اینکه آیا به سبب رحمت خداوند است یا غضب او، نعمت است یا نقمت، با چشم ظاهر دیده نمی‌شود، بلکه با چشم دل قابل‌مشاهده است.\nپیامبر خاتم می‌فرمایند:\n«لَوْلَا أَنَّ الشَّیاطِینَ یحُومُونَ عَلَی قُلُوبِ بَنِی آدَمَ لَنَظَرُوا إِلَی مَلَکوتِ السَّمَاوَاتِ وَالْأَرْضِ»\nاگر شیاطین گرداگرد قلب فرزندان آدم نمی‌چرخیدند، آنان به ملکوت آسمان‌ها و زمین دست می‌یافتند. همه این برکات با قدم‌گذاشتن در مسیر تقوا حاصل می‌شود.\n«وَشِفَاءُ مَرَضِ أَجْسَادِکمْ»\n۳. تقوا بیماری‌های جسم شما را نیز شفا می‌دهد. تقوا چگونه بیماری‌های جسمی را درمان می‌کند؟ همان‌گونه که در خطبه‌های قبل، درباره شفای دردها با قرآن توضیحات کاملی داده شد، در اینجا نیز همین موضوع مطرح است. انسان به این موضوع اهمیت می‌دهد که چه چیزی بخورد، چگونه بخورد و چه مقدار غذا مصرف کند. همین درست و به‌اندازه غذاخوردن، بخش زیادی از دردها و بیماری‌ها را کاهش می‌دهد و درمان می‌کند. این موارد از آثار تقواست. قرآن می‌فرماید:\n«فَلْینْظُرِ الْإِنْسَانُ إِلَی طَعَامِهِ»؛ انسان باید به طعام خود بنگرد. این توجه هم به حلال و حرام بودن غذا مربوط است و هم به مقدار و آداب غذاخوردن. اگر این موارد رعایت شوند، بیماری‌ها دفع می‌شوند.\nپیامبر فرمودند:\n«الْمُؤْمِنُ یأْکلُ فِی مِعَاءٍ وَاحِدٍ وَالْکافِرُ یأْکلُ فِی سَبْعَةِ أَمْعَاءٍ»؛ مؤمن با یک معده و شکم غذا می‌خورد و کافر با هفت معده. مقصود این است که مؤمن بسیاری از غذاها را به‌خاطر حرمت، نجاست یا پرهیز از پرخوری ترک می‌کند؛ اما کافر هرچه به دستش برسد، می‌خورد و هیچ محدودیتی را رعایت نمی‌کند.\n«وَصَلَاحُ فَسَادِ صُدُورِکمْ»\n۴. اصلاح فساد سینه‌های شما با تقواست. تقوا سبب اصلاح سینه و پاک‌شدن آلودگی‌های درونی شما می‌شود.\n«وَطُهُورُ دَنَسِ أَنْفُسِکمْ»\n۵. پاکی و طهارت جان شما باتقوا حاصل می‌شود. تقوا موجب پاک‌شدن شما از آلودگی‌هاست. یکی از مراتب بصیرت، گشوده‌شان چشم دل است و تقوا به آن جلا می‌بخشد. ازبین‌بردن آلودگی‌های اخلاقی، مانند وسواس و حسد، و آلودگی‌های عقیدتی، مانند شک، نفاق و شرک، باتقوا ممکن است. مؤمن هم طهارت ظاهری دارد و هم طهارت قلبی.\nاهل‌بیت به مرحله طهارت رسیده‌اند:\n«إِنَّمَا یرِیدُ اللَّهُ لِیذْهِبَ عَنْکمُ الرِّجْسَ أَهْلَ الْبَیتِ وَیطَهِّرَکمْ تَطْهِیراً».\nما نیز می‌توانیم به‌اندازه توان خود، در سایه‌سار تقوا به طهارت برسیم.\n«وَجِلَاءُ غِشَاءِ أَبْصَارِکمْ»\n۶. تقوا، کم‌بینایی و پوشش [غِشَاءِ] چشم انسان را برطرف می‌کند و به آن جلا می‌بخشد.\n«وَأَمْنُ فَزَعِ جَأْشِکمْ»\n۷. تقوا باعث امنیت و آرامش شما می‌شود. تقوا قلب شما را از تپش‌های [جَأْشِکمْ] بیهوده و اضطراب حفظ می‌کند. باتقوا، در شرایط سخت زندگی آرامش خود را حفظ می‌کنید؛ اما بی‌تقوایی می‌تواند به افسردگی، اضطراب و نیاز به مصرف قرص‌های اعصاب منجر شود.\nامیرالمؤمنین در سخت‌ترین لحظات جنگ، هنگامی که عسلی را از دست یکی از یارانشان چشیدند، فرمودند:\n«هَذَا عَسَلٌ طَائِفِی»؛ یعنی این عسل متعلق به طائف است. حضرت در آن شرایط سخت جنگ، متوجه طعم عسل بودند و تشخیص می‌دادند که از کدام منطقه به‌دست‌آمده است. هیچ حادثه بیرونی نمی‌تواند قلب امیرالمؤمنین را تحت‌تأثیر قرار دهد.\n«وَضِیاءُ سَوَادِ ظُلْمَتِکمْ»\n۸. تقوا روشنایی‌بخش تاریکی و سیاهی [سَوَادِ] درون شماست. در تاریکی‌ها و گذرگاه‌های صعب‌العبور زندگی، این تقواست که چراغ راه ما خواهد شد.\n«اجْعَلُوا طَاعَةَ اللَّهِ شِعَارًا دُونَ دِثَارِکمْ»\nحضرت برای اطاعت از خدا چهار مرحله را بیان می‌کنند:\nمرحله اول، طاعت ظاهری است؛ یعنی تقوا باید در ظاهر امور انسان مشخص باشد و انسان ظاهرالصلاح باشد. نکته مهم این است که ظاهر طاعت با تظاهر به طاعت تفاوت دارد. انسان منافق به طاعت تظاهر می‌کند؛ یعنی خود را به رنگ مؤمنان درمی‌آورد، درحالی‌که در واقع اهل طاعت نیست. اما مؤمن بنده خداست و باید ظاهر او نیز مطابق خواست خداوند باشد.\nمرحله دوم، طاعت پوستی است؛ یعنی طاعتی که با تمام پیکر ما تماس و همراهی دارد. انسان نباید به طاعت ظاهری اکتفا کند، بلکه باید روزبه‌روز طاعت را در وجود خود نهادینه‌تر کند.\n«وَدَخِیلًا دُونَ شِعَارِکمْ»\nمرحله سوم، واردکردن طاعت به درون وجود است؛ یعنی طاعت باید با پوست، گوشت و استخوان ما عجین شود.\n«وَلَطِیفًا بَینَ أَضْلَاعِکمْ»\nمرحله چهارم، واردکردن اطاعت به قلب، همراه بالطافت است. [أَضْلَاعِکمْ] به استخوان‌های دنده اشاره دارد. آخرین مرحله اطاعت، مطیع شدن قلب انسان است؛ به‌گونه‌ای که نه‌تنها ظاهر و اعضای او مطیع خدا باشند، بلکه قلبش نیز از هیچ‌یک از دستورات الهی دلگیر نشود و از آن‌ها سرپیچی نکند.\nنکته‌ای که در جمله حضرت وجود دارد، این است که قلب لطیف است و باید امور را بالطافت در آن وارد کرد. با مداومت بر اعمال، انس‌گرفتن و رفاقت می‌توان قلب را تغییر داد و آن را به مرحله اطاعت قلبی رساند.\n«وَأَمِیرًا فَوْقَ أُمُورِکمْ»\nاطاعت از خدا را امیر تمام امور خود قرار دهید. ما امور شخصی، اجتماعی، عبادی و... بسیاری داریم؛ در تمام این امور، فرمانده و امیر باید اطاعت از خدا باشد. هر کاری را باید با معیار فرمان او بسنجیم؛ اگر او تأیید کرد، باید آن را انجام دهیم. سرباز هیچ‌گاه نباید از فرمان امیر و فرمانده خود سرپیچی کند.\nامیرالمؤمنین در حکمت‌های نهج‌البلاغه فرمودند:\n«کمْ مِنْ عَقْلٍ أَسِیرٍ تَحْتَ هَوَی أَمِیرٍ»؛ چه بسیار عقل‌هایی که اسیر هوای نفسی هستند که بر آن‌ها فرمانروایی می‌کند. درحالی‌که عقل باید امیر و فرمانروا باشد.\n«وَمَنْهَلًا لِحِینِ وُرُودِکمْ»\nاطاعت از خدا را آبشخوری [مَنْهَلًا] برای ورود و نوشیدن آب حیات قرار دهید. باید از چشمه‌سار اطاعت از خدا آب نوشید. مؤمن همیشه تشنه است؛ تشنه خدا، تشنه معارف و تشنه محبت امیرالمؤمنین. این تشنگی با آب دنیایی برطرف نمی‌شود، بلکه عطش قلب با اطاعت از خدا سیراب می‌شود.\n«وَشَفِیعًا لِدَرْک طَلِبَتِکمْ»\nبرای رسیدن به تمام خواسته‌های خود، اطاعت از خدا را شفیع قرار دهید تا به‌واسطهٔ این شفیع به خواسته‌هایتان برسید.\nنیاز انسان به اطاعت بعد از مرگ:\n«وَجُنَّةً لِیوْمِ فَزَعِکمْ»\nاطاعت از خدا را سپر [جُنَّةً] روزهای سخت و هراسناک [فَزَعِکمْ] پس از مرگ قرار دهید.\nامیرالمؤمنین در خطبه ۲۰ فرمودند:\n«فَإِنَّکمْ لَوْ قَدْ عَاینْتُمْ مَا قَدْ عَاینَ مَنْ مَاتَ مِنْکمْ لَجَزِعْتُمْ وَوَهِلْتُمْ»؛ اگر آنچه را کسی که از میان شما مرده است، هنگام مرگ مشاهده کرده، شما زندگان نیز می‌دیدید، قطعاً دچار جزع، فزع و اضطراب می‌شدید. اما خدای متعال نخستین عضوی را که از کار می‌اندازد، زبان است تا محتضر نتواند از اخبار آن جهان برای زندگان چیزی بگوید؛ وگرنه زندگی بر انسان تلخ خواهد شد.\n«وَمَصَابِیحَ لِبُطُونِ قُبُورِکمْ»\nاطاعت از خدا، چراغ روشنایی‌بخش تاریکی قبر شماست.\n«وَسَکنًا لِطُولِ وَحْشَتِکمْ»\nاطاعت از خدا باعث آرامش و سکون شما در دوران طولانی وحشت می‌شود. گاهی طولانی‌شدن حساب‌وکتاب، عذابی است که به شخص داده می‌شود و اطاعت از خدا، مایه آرامش انسان در سختی‌هاست.\n«وَنَفَسًا لِکرَبِ مَوَاطِنِکمْ»\nاطاعت از خدا گشایشی برای منزلگاه‌های سختی است که پیشرو دارید.\nاللَّهُمَّ لَا تُزِغْ قُلُوبَنَا وَثَبِّتْ أَقْدَامَنَا.","بخش دوم\nمتن:\nترجمه:\nتفسیر:\nکتاب فیض‌الاسلام، ۱۸۹\nحضرت در این خطبه هشت اثر تقوا را بیان کردند که سرانجام تقوای الهی، اطاعت است؛ یعنی سرانجامِ انسان متقی، مطیع بودن محض است. حضرت، تقوا و اطاعت را در دو بخش و در مجموع هشت مورد توصیف کردند.\nفَإِنَّ طاعَةَ اللهِ حِرْزٌ مِنْ مَتالِفِ مُکتَنِفَةٍ\nاطاعت، حصار و حافظی است که محیط اطراف شما را فراگرفته است. بدانید تقوا و اطاعت از خدا باعث می‌شود از تمام چیزهایی که موجب تلف‌شدن شما می‌شوند، یعنی «مَتالِف»، محفوظ بمانید.\n«مَتالِف» خطرهایی هستند که محیط اطراف انسان را فراگرفته‌اند و هر لحظه ممکن است به انسان آسیب برسانند.\nوَ مَخاوِفَ مُتَوَقَّعَةٍ\nبدانید اطاعت از خدا می‌تواند شما را از امور خوفناک و خطرهایی که انتظار وقوعشان را دارید، یعنی «مَخاوِفَ مُتَوَقَّعَةٍ»، حفظ کند.\nوَ أَوارِ نِیرانٍ مُوقَدَةٍ\nبدانید اطاعت از خدا می‌تواند آتش‌های برافروخته را از انسان دور کند. این سه جمله، به‌نوعی به دنیای ما و به‌نوعی به آخرت ما مربوط می‌شوند. انسان در دنیا با مهلکه‌ها و خطرهایی روبه‌روست؛ آتش‌هایی که اگر انسان در آن‌ها گرفتار شود، تمام حیثیت و آبروی او را می‌سوزانند. ایمان و اطاعت از خدا، حافظ و نگهدارنده ما در برابر خطرهایی است که دائماً در معرض آن‌ها قرار داریم.\nاز طرفی، آخرت نیز خطرهایی دارد و ایمان، تقوا و اطاعت، ما را از آن امور اخروی حفظ می‌کنند.\nچهار مورد از آثار دفعی تقوا\nفَمَنْ أَخَذَ بِالتَّقْوی عَزَبَتْ عَنْهُ الشَّدائِدُ بَعْدَ دُنُوِّها\n۱. پس از نزدیک‌شدن سختی‌ها، این تقواست که آن مشکلات را دور می‌کند؛ یعنی «عَزَبَتْ».\nاین اثر، حالت تدافعی دارد. وقتی تقوا در انسان به ملکه‌ای پایدار تبدیل و نهادینه شود، به‌تدریج مشکلات را دفع می‌کند. هرکس تقوا را محکم بگیرد، سختی‌ها و شدت مشکلات از او دور می‌شوند؛ حتی پس از آنکه به او نزدیک شده باشند.\nیکی از همین سختی‌ها و بدبختی‌های دنیا، همنشینی با انسان گناهکار است. انسان متقی با هرکسی نشست‌وبرخاست نمی‌کند؛ به همین دلیل، از عذاب‌ها و سختی‌هایی که در اثر همنشینی با گناهکار به وجود می‌آیند، دور می‌ماند. همنشینی با انسان احمق نیز گرفتاری است. انسان متقی، چون با احمق مراوده ندارد، از این سختی‌ها دور می‌ماند.\nاِحْلَوْلَتْ لَهُ الْأُمُورُ بَعْدَ مَرارَتِها\n۲. امور زندگی برای اهل تقوا، پس از آنکه زندگی پر از مرارت و دلهره بوده است، بسیار شیرین می‌شوند؛ یعنی «اِحْلَوْلَتْ».\nتقوا تلخی‌های روزگار را به شیرینی تبدیل می‌کند و به ما امکان می‌دهد از زندگی لذت ببریم. سختی وجود دارد، اما این سختی با شیرینی همراه است. بازیکن فوتبال در میانه بازی زحمت می‌کشد، اما چون به بازی عشق می‌ورزد، از آن لذت می‌برد. کسی هم که تقوا دارد، رنج و زحمت را تحمل می‌کند و برایش شیرین است؛ زیرا خودش این مسیر را انتخاب کرده است.\nدر خطبه ۱۳۰ آمده است: وقتی خلیفه سوم، ابوذر غفاری را تبعید کرد، مردم را از بدرقه او منع کرد؛ اما امیرالمؤمنین و حسنین به بدرقه او رفتند. حضرت فرمود:\n«وَلَوْ أَنَّ السَّماواتِ وَالْأَرَضِینَ کانَتا عَلی عَبْدٍ رَتْقاً ثُمَّ اتَّقی یجْعَلِ اللهُ لَهُ مِنْهُما مَخْرَجاً»\nاگر درهای آسمان و زمین بر کسی بسته شود، ولی او تقوای الهی را رعایت کند، خداوند برایش راه‌گشایشی باز می‌کند. در هر سختی و زحمتی، تقوا راه را برای انسان باز می‌کند و او را پیش می‌برد.\n«وَلا یؤْنِسَنَّک إِلَّا الْحَقُّ»\nمبادا با چیزی جز حق انس بگیرید.\n«وَلا یوحِشَنَّک إِلَّا الْباطِلُ»\nمبادا از چیزی جز باطل وحشت کنید.\nاگر به این حقیقت توجه داشته باشیم، با کفار سر سازش نخواهیم داشت.\n«فَلَوْ قَبِلْتَ دُنْیاهُمْ لَأَحَبُّوک، وَلَوْ فَرَضْتَ مِنْها لَأَمَّنُوک»\nای ابوذر، اگر بر سفره فساد عثمان می‌نشستی، تو را دوست می‌داشتند؛ اما چون در برابر آن‌ها ایستادی، تحریم و تبعید شدی. ممنوع‌کردن مردم از بدرقه تو، نشان می‌دهد که راهت درست است.\nاِنْفَرَجَتْ عَنْهُ الْأَمْواجُ بَعْدَ تَراکمِها\n۳. پس از آنکه امواج بلا به‌سوی شما روی می‌آورند و روی‌هم انباشته می‌شوند، تقوا می‌تواند آن‌ها را از هم باز کند و کنار بزند؛ یعنی «اِنْفَرَجَتْ». با کنار رفتن امواج متراکم، راه باز می‌شود.\nحضرت در نهج‌البلاغه، واژه «امواج» را در دو مورد به کار می‌برند.\n۱. «أَیهَا النّاسُ، شُقُّوا أَمْواجَ الْفِتَنِ بِسُفُنِ النَّجاةِ»\nای مردم، امواج فتنه را با کشتی‌های نجات بشکافید. منظور از کشتی‌های نجات، اهل‌بیت هستند؛ سفینه‌هایی که انسان را از امواج فتنه عبور می‌دهند. هرگاه امواج فتنه بر شما شدت گرفت، به تقوا چنگ بزنید؛ زیرا تقوا شما را از امواج فتنه نجات می‌دهد.\n۲. کاربرد دیگر امواج، در مورد بلاست. در حکمت ۱۴۶ آمده است:\n«صُونُوا إِیمانَکمْ بِالصَّدَقَةِ، وَحَصِّنُوا أَمْوالَکمْ بِالزَّکاةِ، وَادْفَعُوا أَمْواجَ الْبَلاءِ بِالدُّعاءِ»\nایمان خود را با صدقه حفظ کنید، اموالتان را با زکات مصون بدارید و امواج کمرشکن بلا را با دعا دفع کنید.\nپس امواج، هم به معنای فتنه و هم به معنای بلاست. اگر می‌خواهید تراکم بلاها را از بین ببرید، باید به دعا و تقوا روی بیاورید. تقوا می‌تواند در سختی‌های کمرشکن به یاری انسان بیاید. آسان‌شدن امور دشوار، یکی از آثار تقواست.\nوَ أَسْهَلَتْ لَهُ الصِّعابُ بَعْدَ إِنْصابِها\n۴. تقوا امور دشوار را برای انسان آسان می‌کند؛ یعنی «أَسْهَلَتْ». این اتفاق پس از آن رخ می‌دهد که رنج و زحمت خسته‌کننده، یعنی «إِنْصاب»، او را فراگرفته باشد.\nتقوا می‌تواند در سختی‌های کمرشکن که انسان را به‌شدت خسته می‌کنند، به یاری او بیاید و امور دشوار را آسان کند. قرآن کریم می‌فرماید:\n«وَاتَّقُوا اللهَ وَیعَلِّمُکمُ اللهُ»؛ بقره، ۲۸۲.\nتقواپیشه کنید تا خداوند به شما بیاموزد. بسیاری از آموخته‌های انسان، در پرتو تقوا و نماز شب به دست می‌آیند.\nسیدرضی رحمه‌الله در ۴۷ سالگی از دنیا رفت؛ اما اکنون حدود ۱۱۰۰ سال است که شیعیان بر سفره نهج‌البلاغه او نشسته‌اند و با امیرالمؤمنین آشنا می‌شوند. انسان حتی در سن کم نیز می‌تواند اوج بگیرد. باتقوا، کارهای دشوار برای انسان آسان می‌شوند و می‌توان راه صدساله را در سی‌سال پیمود.\nچهار مورد از آثار عطایی تقوا\nهَطَلَتْ عَلَیهِ الْکرامَةُ بَعْدَ قُحُوطِها\n۱. وقتی انسان متقی شود، کرامت و بزرگواری بر او سرازیر می‌شود؛ یعنی «هَطَلَتْ»، درحالی‌که پیش از تقوا، دچار قحطی کرامت بود؛ یعنی «قُحُوطِها».\nسروری و عزت در گرو تقواست. پس از قحطی، باران کرامت بر این شخص می‌بارد.\nانسانی که تقوا ندارد، گویی گرفتار قحطی است؛ اما باتقوا، باران کرامت بر او فرومی‌ریزد.\nانسان باتقوا عزیز است و انسان بی‌تقوا ذلیل.\nواژه «کرامت» در نهج‌البلاغه معنای خاصی دارد. حضرت از کرامت هم در دنیا و هم در آخرت سخن گفته‌اند.\nدرباره مبعث فرمودند:\n«وَقَدْ بَلَغْتُمْ مِنْ کرامَةِ اللهِ تَعالی لَکمْ مَنْزِلَةً تُکرَمُ بِها إِماؤُکمْ»\nشما به برکت اسلام به کرامت رسیدید؛ به برکت اسلام عزیز شدید و زندگی دنیایی شما رنگ کرامت گرفت.\nتعبیر حضرت این است که کنیزان نیز به برکت اسلام گرامی داشته شدند. مردم به سبب همسایگی با مسلمان، حتی شخص مشرک را نیز گرامی می‌داشتند. کرامت، انسان را عزیز می‌کند. اسلام در دنیا به شما عزت می‌بخشد؛ پس تقوا داشته باشید تا به کرامت برسید.\nکرامت هم در دنیا وجود دارد و هم در آخرت. حضرت در خطبه ۸۶ فرمودند:\n«الصّادِقُ عَلی شَفا مَنْجاةٍ وَکرامَةٍ»\nانسان صادق در آستانه نجات و کرامت قرار دارد. انسان راست‌گو در دنیا عزیز است؛ اما دروغگو در دنیا ذلیل و در ورطه هلاکت است.\nبخشی از کرامت، دنیایی و بخشی دیگر، اخروی است. درباره کرامت اخروی، در خطبه ۱۸۳ آمده است:\n«وَینْزِلُهُ مَنْزِلَةَ الْکرامَةِ عِنْدَهُ فِی دارٍ اصْطَنَعَها لِنَفْسِهِ»\nخداوند انسان متقی را در خانه‌ای جای می‌دهد که برای خود برگزیده است. کرامت در دنیا به معنای عزت و آزادی است و کرامت در آخرت به معنای بهشت.\nهمان بهشتی که در خطبه ۱۸۳ آمده است؛ آنچه درباره بهشت به شما گفته‌اند، تنها وصف ورودی آن است و درون بهشت، خبرهای دیگری وجود دارد. خود بهشت، رضوان الهی و محبت به اهل‌بیت است. انسان متقی، پس از آنکه گرفتار قحطی کرامت شده بود، به‌واسطهٔ تقوا و ایمان، باران رحمت را بر سرخود می‌بیند.\nتَحَدَّبَتْ عَلَیهِ الرَّحْمَةُ بَعْدَ نُفُورِها\n۲. رحمت، پس از آنکه از انسان دور شده بود، به‌سوی انسان متقی بازمی‌گردد و او را در برمی‌گیرد؛ یعنی «تَحَدَّبَتْ».\nپیش از تقوا، لطف و رحمتی در کار نبود؛ اما پس از به‌دست‌آوردن تقوا، رحمت بازمی‌گردد و انسان را احاطه می‌کند.\nرحمت دو قسم است:\n۱. رحمانیت که شامل همه موجودات است؛ انسان و غیرانسان، مؤمن و غیر مؤمن.\n۲. رحیمیت که مخصوص مؤمنان و بندگان است. این رحمت، نصیب انسان متقی می‌شود.\nتَفَرَّجَتْ عَلَیهِ النِّعَمُ بَعْدَ نُضُوبِها\n۳. نعمت‌های الهی پس از آنکه فروکش کرده بودند، به‌سوی انسان متقی جاری می‌شوند؛ یعنی «تَفَرَّجَتْ»، پس از آنکه نعمت‌ها روبه‌کاهش گذاشته بودند؛ یعنی «نُضُوبِها».\nاگر متقی باشید، رحمت الهی بر شما فرومی‌ریزد. قرآن کریم می‌فرماید:\n«وَلَوْ أَنَّ أَهْلَ الْقُری آمَنُوا وَاتَّقَوْا لَفَتَحْنا عَلَیهِمْ بَرَکاتٍ مِنَ السَّماءِ وَالْأَرْضِ»؛ اعراف، ۹۶.\nاگر مردم ایمان بیاورند و تقواپیشه کنند، درهای برکات آسمان و زمین را به روی آنان می‌گشاییم.\nوَ بَلَّتْ عَلَیهِ الْبَرَکةُ بَعْدَ إِرْذاذِها\n۴. باران شدید برکت بر انسان متقی می‌بارد؛ یعنی «بَلَّتْ»، پس از آنکه بارش برکت از او دریغ شده بود؛ زیرا تقوایی در کار نبود.\nباران شدید برکت بر انسان متقی می‌بارد، پس از آنکه باران رحمت برای او تنها به‌صورت نم‌نم بود؛ یعنی «إِرْذاذِها».\nهشت اثر تقوا بر انسان متقی\n«فَمَنْ أَخَذَ بِالتَّقْوی»\nیعنی کسی که تقوا را در پیش بگیرد. تا زمانی که انسان به این ریسمان چنگ نزند، از این هشت صفت نیز خبری نخواهد بود.\nفَاتَّقُوا اللهَ الَّذی نَفَعَکمْ بِمَوْعِظَتِهِ\nپس تقوای الهی پیشه کنید؛ همان خدایی که با موعظه‌هایش به شما سود رساند. آثار تقوا در قیامت، نمود بیشتری پیدا می‌کنند.\nوَ وَعَظَکمْ بِرِسالَتِهِ\nاز پند و موعظه‌ای بهره ببرید که خداوند به‌واسطهٔ پیامبران برای شما فرستاده است.\nامروز مبعث است؛ پیامبری به‌سوی شما آمده است. معارف و مطالب او را فرابگیرید؛ زیرا تقوا در همین معارف نهفته است تا رشد کنید.\nوَ امْتَنَّ عَلَیکمْ بِنِعْمَتِهِ\nخداوند با نعمت‌هایش بر شما منت نهاد.\nنعمت‌های خدا فراوان‌اند. یکی از این نعمت‌ها، وجود پیامبر رحمتٌ للعالمین است. شکر این نعمت، با شناختن و به‌کاربستن دستورات ایشان تحقق می‌یابد.\nفَعَبِّدُوا أَنْفُسَکمْ لِعِبادَتِهِ\nنفس خود را برای اطاعت از خدا به بندگی وادار کنید؛ یعنی «فَعَبِّدُوا».\nنفس انسان سرکش است. در نهج‌البلاغه آمده است که هیچ کار خوبی نیست که به نفس عرضه کنیم و نفس از آن اکراه نداشته باشد؛ نفس از نماز کراهت دارد و بیکاری را دوست دارد. بدانید که باید نفس را تأدیب کنید تا کار خوب انجام دهد.\nوَ اخْرُجُوا إِلَیهِ مِنْ حَقِّ طاعَتِهِ\nحق اطاعت خدا را به‌جا آورید و خود را از مسئولیت انجام‌وظیفه در برابر او بری‌الذمه کنید. حق خدا را ادا کنید و فرمان او را به‌جا آورید. هیچ‌کس نمی‌تواند حق اطاعت خدا را آن‌گونه که شایسته است، به طور کامل ادا کند.\n«ما عَرَفْناک حَقَّ مَعْرِفَتِک وَما عَبَدْناک حَقَّ عِبادَتِک»\nما تو را آن‌گونه که شایسته شناخت توست، نشناختیم و آن‌گونه که شایسته عبادت توست، عبادت نکردیم. بااین‌حال، هرکس باید در حد توان خود حق خدا را به‌جا آورد.\nکسی با حواس‌پرتی نماز می‌خواند و دیگری با حضور قلب. اما اداکردن حق نماز به چه معناست؟\nوقتی می‌گوییم «إِیاک نَعْبُدُ وَإِیاک نَسْتَعِینُ»، یعنی من موحد محض هستم و می‌خواهم به خدا بگویم: خدایا، آمده‌ام گزارش کارم را به تو بدهم. این، یکی از جلوه‌های اداکردن حق نماز است.\nاز آیت‌الله بهجت نقل شده است که نماز، نمود روز شماست. اگر غافل باشید، نمازتان با حواس‌پرتی همراه می‌شود؛ اما اگر همواره به خدا توجه داشته باشید، نماز را به‌خوبی به‌جا می‌آورید. باید حق عبادت را ادا کنیم. خداوند به ما نعمت قدرت و توانایی داده است.\nبحث اسلام\nثُمَّ إِنَّ هذَا الْإِسْلامَ دینُ اللهِ الَّذی اصْطَفاهُ لِنَفْسِهِ\nرسیدن به تقوا ممکن نیست، مگر از طریق دین. انسان متقی باید در چارچوب دین زندگی کند.\nاسلامی که موجب تقوا می‌شود، دینی است که خداوند برای خود برگزیده است.\n«إِنَّ الدِّینَ عِنْدَ اللهِ الْإِسْلامُ وَمَنْ یبْتَغِ غَیرَ الْإِسْلامِ دیناً فَلَنْ یقْبَلَ مِنْهُ»؛ آل‌عمران، ۸۵.\nکسانی که سخن دین را شنیده‌اند، باید بدانند که پس از اسلام، دینی دیگر از کسی پذیرفته نمی‌شود.\nوَ اصْطَفاهُ عَلی عَینِهِ\nاسلام دینی است که خداوند آن را در پیشگاه خود پرورش داد و برگزید.\nاحکام و شریعت دین را با حساسیت فراوان برای شما واجب و حرام کرد. خداوند به این دین و احکام شریعت عنایت داشت. این دین شما را به هر مقصدی که باید به آن برسید، می‌رساند.\nوَ اصْطَفاهُ خِیرَةَ خَلْقِهِ\nپس از استوارکردن احکام دین، خداوند بهترین مخلوقات خود را برای ابلاغ و رساندن دین برگزید؛ یعنی پیامبر خاتم، محمد مصطفی صلی‌الله علیه و آله.\nقرآن کریم می‌فرماید که برخی پیامبران بر برخی دیگر فضیلت دارند. نبی و رسول از جایگاه والایی برخوردارند و پیامبر اسلام در میان‌برترین‌ها، برترین است.\nدر جریان معراج، هنگامی که پیامبر و جبرئیل به سدره‌المنتهی رسیدند، جبرئیل نتوانست از آنجا فراتر برود. پیامبر از جبرئیل که یکی از چهار فرشته مقرب خداست، مرتبه‌ای بالاتر دارد.\nدر کتاب عیون اخبار الرضا، شیخ صدوق در شرح معجزات امام هشتم آورده است که مأمون با کنایه و نیش و کنایه امام رضا را آزار داد.\nامام هشتم ناراحت شدند و به خانه بازگشتند. اباصلت هروی می‌گوید که دیدم حضرت زیر لب زمزمه می‌کنند:\n«یا بَدیعُ، یا قَوِی، یا مَنیعُ، یا عَلِی، یا رَفیعُ»\nحضرت نمازی خواندند و پس از نماز، شهر زیرورو شد.\nدرباره شأن پیامبر آمده است:\n«صَلِّ عَلی مَنْ شَرَّفْتَ صَلاتَک بِالصَّلاةِ عَلَیهِ»\nخدایا، بر کسی درود بفرست که با درود فرستادن بر او، نماز را شرافت بخشیدی.\nنماز بدون تشهد، شرافت ندارد. نماز، ستون و خیمه دین است. نماز بدون صلوات بر پیامبر، ناقص است. مهم‌ترین اعمال دینی ما نماز است؛ اما یکی از ارکان نماز، صلوات بر پیامبر و آل پیامبر است.\nوَ أَقامَ دَعائِمَهُ عَلی مَحَبَّتِهِ\nخداوند پایه‌های دین را بر محبت خود استوار کرد. دین، بامحبت معنا می‌یابد؛ اگر محبت از دین اسلام گرفته شود، دیگر حقیقت دین باقی نمی‌ماند.\nاساس و ارکان دین، محبت به خداست. وقتی عاشق باشیم، همه سختی‌ها را به جان می‌خریم. در مناجات شعبانیه آمده است:\n«إِلهی لَمْ یکنْ لی حَوْلٌ فَأَنْتَقِلَ بِهِ عَنْ مَعْصِیتِک إِلّا فی وَقْتٍ أَیقَظْتَنی لِمَحَبَّتِک»\nخدایا، من نیرویی ندارم که به‌وسیله آن از گناه دوری کنم؛ مگر آن زمان که مرا بامحبت خود بیدار کنی. عشق به خدا بیدارکننده است و انسان با عشق به محبوب بیدار می‌شود.\nدین باید عاشقانه باشد. باید بتوان جوانان و جامعه را با عشق به خدا آشنا کرد. انسان دوستدار زیبایی‌هاست؛ بنابراین، جوانان باید با خداوندی آشنا شوند که جمیل و زیباست.\nمشکل از ماست؛ ما خدا را بد جلوه داده‌ایم. در روایات آمده است که باخدا ناز کنید؛ یعنی ناز خدا را بخرید و عاشقانه با او برخورد کنید.\nأَذَلَّ الْأَدْیانَ بِعِزَّتِهِ\nدین با چنین ویژگی برجسته‌ای آمد و در برابر عزت اسلام، دیگر ادیان ناتوان و خوار شدند؛ یعنی «أَذَلَّ». خداوند به اسلام عزتی بخشید که دیگر ادیان در برابر آن در مرتبه‌ای پایین‌تر قرار گرفتند.\nوَ وَضَعَ الْمِلَلَ بِرَفْعِهِ\nادیان و آیین‌های گوناگون در برابر رفعت اسلام سر فرود آوردند و در مرتبه‌ای پایین‌تر قرار گرفتند؛ یعنی «وَضَعَ».\nخداوند با بالابردن جایگاه اسلام، دیگر ملت‌ها و نحله‌ها و آیین‌ها را در مرتبه‌ای پایین‌تر قرارداد.\n«هُوَ الَّذی أَرْسَلَ رَسُولَهُ بِالْهُدی وَدینِ الْحَقِّ لِیظْهِرَهُ عَلَی الدِّینِ کلِّهِ»؛ فتح، ۲۸.\nاسلام آمد تا بر همه ادیان غالب شود.\nوَ أَهانَ أَعْداءَهُ بِکرامَتِهِ\nخداوند باکرامت بخشیدن به اسلام، دشمنان آن را خوار کرد.\nوقتی اسلام را کریم و گرامی داشت، دیگران در برابر آن خوار شدند.\nوَ خَذَلَ مُحادّیهِ بِنَصْرِهِ\nخداوند با یاری‌رساندن به اسلام، دشمنان و مخالفان آن، یعنی «مُحادّیه»، را به خفت و خواری انداخت.\nوَ هَدَمَ أَرْکانَ الضَّلالَةِ بِرُکنِهِ\nخداوند با استواری ارکان اسلام، ستون‌های ضلالت و گمراهی را ویران کرد؛ یعنی «هَدَمَ».\nارکان اسلام، مانند شریعت محکم، امام، قرآن، رسول و عقل، استوارند؛ اما ضلالت و گمراهی ضعیف و بی‌پایه‌اند و مانند خانه‌ای بر آب می‌مانند که باید به چیزی تکیه کنند.\nامیرالمؤمنین می‌فرماید:\n«إِنَّما سُمِّیتِ الشُّبْهَةُ شُبْهَةً لِأَنَّها تُشْبِهُ الْحَقَّ»\nشبهه را شبهه می‌گویند؛ زیرا خود را شبیه حق می‌کند. اگر باطل از حق جدا شود، هیچ‌کس به‌سوی باطل نمی‌رود. اگر حق آشکارا بیان شود، ضلالت و گمراهی نابود می‌شود.\nعده‌ای از اصحاب به معاویه ناسزا می‌گفتند. حضرت فرمودند که دوست ندارم شما جزو ناسزاگویان باشید:\n«إِنِّی أَکرَهُ لَکمْ أَنْ تَکونُوا سَبّابِینَ»\nحق را آشکار کنید تا کسی به باطل تمایل پیدا نکند.\nوَ سَقی مَنْ عَطِشَ مِنْ حِیاضِهِ\nخداوند به‌واسطهٔ دین، تشنگان معرفت را سیراب کرد؛ یعنی «سَقی». کسی که تشنه باشد، از حوض‌های اسلام، یعنی «حِیاضِهِ»، سیراب می‌شود.\nشرط بهره‌برداری از معارف اسلام، تشنگی است و شرط استفاده از قرآن، طهارت است.\n«لا یمَسُّهُ إِلَّا الْمُطَهَّرُونَ»؛ واقعه، ۷۹.\nبرای علم تشنه باشید و عطش فراگیری داشته باشید تا شما را به مقصد برسانند. خداوند فیاض است؛ یعنی فیض می‌رساند. هرکس تشنه باشد، می‌تواند از فیض او بهره‌مند شود.\nخداوند تشنگی علمی انسان را سیراب می‌کند.\n«مَنْ طَلَبَنی وَجَدَنی»\nهرکس مرا طلب کند، مرا می‌یابد. ما طالب نیستیم و دغدغه‌ای نداریم؛ به همین دلیل، به جایی نمی‌رسیم.\nفرمودند: اصحاب پیامبر چگونه بودند؟ شیران روز و عابدان شب بودند و به مقامات بالا رسیدند؛ افرادی مانند سلمان و ابوذر.\nوَ أَتاقَ الْحِیاضَ بِمَواتِحِهِ\nخداوند حوض اسلام را به‌واسطهٔ کسانی که از چاه وحی آب می‌کشند، پر کرد؛ یعنی «أَتاقَ» و «مَواتِحِهِ». این افراد، مانند اهل‌بیت، به چاه وحی متصل‌اند؛ از آن آب می‌کشند و در حوض می‌ریزند.\n«الْعُلَماءُ وَرَثَةُ الْأَنْبِیاءِ»\nعالمان ربانی، تشنگان دین را هنگام مراجعه سیراب می‌کنند.\nثُمَّ جَعَلَهُ لَانْفِصامَ لِعُرْوَتِهِ\nخداوند اسلام را چنان قرارداد که دستگیره‌های آن گسستنی نیستند و قوام آن از بین نمی‌رود.\nوَلا فَک لِحَلْقَتِهِ\nحلقه‌های به‌هم‌پیوسته اسلام از یکدیگر جداشدنی نیستند؛ یعنی «لا فَک».\nوَلا انْهِدامَ لِأَساسِهِ\nاساس اسلام ویران شدنی نیست.\nدر طول تاریخ، لطمات زیادی به اسلام وارد کرده‌اند؛ اما حقیقت اسلام به‌هیچ‌وجه ازبین‌رفتنی نیست.\nاساس اسلام چیست؟ در روایتی از پیامبر و امام باقر نقل شده است:\n«لِکلِّ شَیءٍ أَساسٌ، وَأَساسُ الْإِسْلامِ حُبُّنا أَهْلَ الْبَیتِ»\nبرای هر چیزی اساسی وجود دارد و اساس اسلام، محبت ما اهل‌بیت است؛ محبتی که ازبین‌رفتنی نیست.\nحضرت آدم به پیامبر و اهل‌بیت متوسل شد تا نجات پیدا کرد. همه انبیا نیز توسل جستند تا نجات یافتند. اساس، محبت به اهل‌بیت است.\nنکته ۱:\nگفته شد که اساس اسلام از بین نمی‌رود. این موضوع با ظواهر اسلام متفاوت است. در اثر کم‌کاری مسلمانان، ممکن است ظواهر اسلام از بین بروند. ظواهر قابلیت تغییر دارند، اما اصل و اساس اسلام پابرجاست. وظیفه ما حفظ اسلام است.\nنکته ۲:\nوظیفه ما آشناکردن جامعه با اهل‌بیت است. از امام هشتم نقل شده است:\n«لَوْ عَلِمَ النّاسُ مَحاسِنَ کلامِنا لَاتَّبَعُونا»\nاگر مردم می‌دانستند که ما چه می‌گوییم، حتماً از ما پیروی می‌کردند. وظیفه ما حفظ اساس اسلام، یعنی اهل‌بیت، است. باید اهل‌بیت را به همه معرفی کنیم.\nاللَّهُمَّ عَجِّلْ لِوَلِیک الْفَرَجَ، وَاجْعَلْ عَوَاقِبَ أُمُورِنَا خَیرًا.","بخش سوم\nمتن:\nترجمه:\nتفسیر:\n  کتاب فیض‌الاسلام، ۱۸۹\nموضوع: پیامبر و اسلام\nدر ادامه توصیف اسلام، امیرالمؤمنین صلوات‌الله‌علیه فرمودند:\nوَلا زَوالَ لِدَعائِمِهِ\nستون‌های اسلام زوال‌پذیر نیستند.\nوَلا انْقِلاعَ لِشَجَرَتِهِ\nهیچ‌گونه قلع‌وقمعی برای این درخت وجود ندارد؛ درختی که:\n«أَصْلُها ثابِتٌ وَفَرْعُها فِی السَّماءِ»\nریشه‌اش استوار است و شاخه‌اش در آسمان قرار دارد.\nحضرت، اسلام را به درختی تشبیه می‌کنند و این تشبیه نکات قابل‌توجهی دارد:\nدرخت سایه دارد.\nدرخت تکیه‌گاه است.\nدرخت ثمربخش است و میوه دارد.\nدرخت اکسیژن تولید می‌کند.\nدرخت نماد حیات است.\nدرخت همواره در حال رویش و رشد است.\nاسلام نیز چنین است؛ این تشبیهی بسیار بلیغ است.\nاسلام حیات دارد و در سایه آن می‌توان زندگی راحتی داشت.\nتنفس و زنده‌بودن در چارچوب اسلام معنا پیدا می‌کند.\nاسلام ازاین‌جهت به درخت شباهت دارد که درختچه کوچکی نیست که بتوان آن را به‌راحتی حمل و جابه‌جا کرد. درخت کهن‌سال به‌هیچ‌وجه قابل‌انتقال نیست.\nشما نمی‌توانید نظر خود را بر اسلام تحمیل کنید یا آن را بازیچه دست خود قرار دهید. اسلام استوار است و شما باید در محضر آن باشید، نه اینکه آن را به دنبال خود بکشید. احکام اساسی را از آن بگیرید.\nرسول مکرم فرمودند:\n«یا عَلِی أَنْتَ بِمَنْزِلَةِ الْکعْبَةِ»\nای علی، تو به منزله کعبه هستی. مردم باید به‌سوی کعبه بروند؛ کعبه به‌سوی کسی حرکت نمی‌کند. تو نیز به منزله کعبه هستی.\nاسلام مانند کعبه است و در آن قلع‌وقمع و ازبین‌رفتن راه ندارد.\nجبرئیل نزد پیامبر آمد و گفت:\n«قالَ حَبیبِی جَبْرَئِیلُ إِنَّ مَثَلَ هَذَا الدِّینِ کمَثَلِ شَجَرَةٍ ثابِتَةٍ»\nاسلام، درختی استوار است که ریشه‌های آن در خاک فرورفته‌اند.\nدر ادامه، ویژگی‌های این درخت را شرح می‌دهد:\nالْإِیمانُ أَصْلُها: ایمان، اساس و ریشه آن است.\nوَالصَّلاةُ عُرُوقُها: نماز، ریشه‌های آن در زمین و مایه حیات آن است.\nوَالزَّکاةُ ماؤُها: زکات، آب پای درخت اسلام است.\nوَالصَّوْمُ سَعَفُها: روزه، شاخ‌وبرگ درخت است.\nحُسْنُ الْخُلُقِ وَرَقُها: خوش‌اخلاقی، برگ زیبای درخت اسلام است.\nوَالْکفُّ عَنِ الْمَحارِمِ ثَمَرُها: دست‌کشیدن از کارهای حرام، میوه اسلام است.\nای رسول خدا!\n«فَلا تَکمُلُ شَجَرَةٌ إِلَّا بِالثَّمَرِ، کذَلِک الْإِیمانُ لا یکمُلُ إِلَّا بِالْکفِّ عَنِ الْمَحارِمِ»\nدرختی که ثمربخش نباشد و میوه ندهد، بی‌فایده است. درخت با میوه کامل می‌شود.\nاسلامی که انسان را از ارتکاب گناه بازندارد، چاره‌ساز نیست. اسلام با خودداری از محرمات کامل می‌شود.\nوَلا انْقِطاعَ لِمُدَّتِهِ\nمدت و عمر درخت اسلام پایان‌پذیر نیست. اسلام تا روز قیامت باقی می‌ماند و دینی است که بقا دارد.\nوَلا عَفاءَ لِشَرائِعِهِ\nراه‌های رسیدن به اسلام و شریعت‌های آن به‌هیچ‌وجه محو نمی‌شوند؛ یعنی «عَفاء».\nبرای ورود به آب حیات باید از مسیر دین عبور کرد. شریعت اسلام مکتبی است که احکام آن انسان را به خدا و حیات می‌رسانند.\nلا جَذَّ لِفُرُوعِهِ\nشاخه‌های درخت اسلام، یعنی «فُرُوعِهِ»، قطع‌شدنی نیستند؛ یعنی «لا جَذَّ». نه اصل اسلام، نه شریعت و نه فروع آن ازبین‌رفتنی نیستند.\nاهل‌بیت، فروع شریعت را برای امت بیان کردند. چه در دوران غیبت و چه در دوران حضور امام زنده، باید فردی مسئولیت ولایت و صدور حکم را بر عهده داشته باشد و با اجتهاد، احکام را بیان کند.\nدر دوران حیات امامان نیز اجتهاد و صاحب‌نظر بودن وجود داشت و این موضوع تنها به عصر کنونی اختصاص ندارد.\nوَلا ضَنْک لِطَرِیقِهِ\nراه اسلام که گسترده است، هیچ‌گاه تنگ و بسته نمی‌شود؛ یعنی «لا ضَنْک».\nمسیر اسلام آسان است و آسان بودن آن را می‌توان از چند جهت بررسی کرد.\n۱. آسانی ورود به اسلام: پیامبر فرمودند:\n«قُولُوا لا إِلَهَ إِلَّا اللهُ تُفْلِحُوا»\nبگویید «لا إله إلا الله» تا رستگار شوید. به‌محض ورود به اسلام، مال، آبرو و ناموس انسان در مسیر پاکی و حفاظت قرار می‌گیرند.\n۲. استدلالی بودن دین: دین اسلام بر استدلال و عقلانیت استوار است و با منطق و عقل سخن می‌گوید؛ ازاین‌رو، پذیرش آن آسان است.\n۳. آسانی عبادت و توبه: عبادات و توبه در اسلام، در مقایسه با برخی ادیان دیگر، آسان‌تر است.\nدرباره استغفار در ادیان دیگر، خطاب به موسی بن عمران آمده است:\n«یا قَوْمِ إِنَّکمْ ظَلَمْتُمْ أَنْفُسَکمْ بِاتِّخاذِکمُ الْعِجْلَ فَتُوبُوا إِلی بارِئِکمْ فَاقْتُلُوا أَنْفُسَکمْ»؛ بقره، ۵۴.\nای قوم من، شما با گوساله‌پرستی به خودتان ستم کردید؛ پس به‌سوی آفریدگارتان توبه کنید و خودتان را بکشید.\nراه توبه در دین اسلام، استغفار، گریه و ناله است. راه ورود به اسلام باز و آسان است.\nلا وُعُوثَةَ لِسُهُولَتِهِ\nآسانی اسلام هیچ‌گاه به مشقت و دشواری، یعنی «وُعُوثَة»، تبدیل نمی‌شود.\nدین اسلام، باوجود آسانی، دشوار نیست. البته گاهی انسان از شدت راحتی به پلشتی و بی‌نظمی گرفتار می‌شود؛ یعنی هرکس بخواهد، بدون هیچ ضابطه‌ای زندگی کند. اما اسلام چنین نیست.\nاسلام قاعده، قانون، بایدها و نبایدها دارد و باوجود این قوانین، همچنان دینی آسان است.\nبرای مثال، فرورفتن در مرداب و رمل آسان است، اما حرکت در آن‌ها بسیار دشوار می‌شود و انسان در آن‌ها گیر می‌افتد. اسلام آسان است، اما این آسانی به معنای گرفتار کردن انسان نیست؛ بلکه اسلام مسیر حرکت و پویایی را فراهم می‌کند.\nوَلا سَوادَ لِوَضَحِهِ\nروشنی و شفافیت اسلام تا ابد باقی است و هیچ‌گاه به سیاهی و تاریکی، یعنی «سَواد»، نمی‌گراید.\nاسلام مانند برخی ادیان ساختگی، مخوف و پنهان در پس خانه‌ها نیست. دین اسلام شفاف است و همه را نیز به شفافیت دعوت می‌کند.\nوَلا عِوَجَ لِانْتِصابِهِ\nمسیر استوار اسلام به کجی و انحراف، یعنی «عِوَج»، گرایش پیدا نمی‌کند.\n«اهْدِنَا الصِّراطَ الْمُسْتَقِیمَ»\nاسلام، صراطی واضح و روشن است که روبه‌جلو حرکت می‌کند.\nوَلا عَصَلَ فِی عُودِهِ\nستون‌های اسلام، یعنی «عُودِهِ»، کج و مایل نمی‌شوند؛ یعنی «عَصَلَ». در هر شرایطی می‌توان به این ستون‌ها، یعنی وحی، پیامبر، امامان و عقل، تکیه کرد.\nباید به این ستون‌ها اعتماد کرد؛ زیرا در کار آن‌ها کجی و انحرافی نیست.\nوَلا وَغَثَ لِفَجِّهِ\nدره و مسیر گذر اسلام، یعنی «فَجِّهِ»، لغزش و ناهمواری ندارد؛ یعنی «وَغَثَ».\nممکن است مسلمان بلغزد، اما اسلام نورانیت دارد و لغزش‌پذیر نیست. احکام اسلام با یکدیگر تضاد ندارند و یکدیگر را نفی نمی‌کنند.\nوَلا انْطِفاءَ لِمَصابِیحِهِ\nنور و چراغ‌های اسلام، یعنی «مَصابِیحِهِ»، خاموش‌شدنی نیستند؛ یعنی «انْطِفاء». امام حسین، امیرالمؤمنین، نهج‌البلاغه و قرآن، چراغ‌های هدایت‌اند. هرقدر برای شبهه‌پراکنی تلاش کنند، این چراغ‌ها خاموش نمی‌شوند.\nوقتی کلام آنان شنیده شود، دل انسان درگیر و به آن پایبند می‌شود.\nوَلا مَرارَةَ لِحَلاوَتِهِ\nشیرینی اسلام به تلخی، یعنی «مَرارَة»، تبدیل نمی‌شود. هرچه مدت بیشتری از آن بگذرد، تازگی خود را از دست نمی‌دهد.\nیکی از وجوه اعجاز قرآن نیز همین است. قرآن با تکرار کهنه نمی‌شود و تازگی، زیبایی و روشنی خود را حفظ می‌کند.\nعلامه شوشتری کتابی به نام «بهج الصباغه» دارد. ایشان بیست سال برای نگارش آن زمان صرف کرد. گذشت زمان موجب فرسودگی آن نشد و هر بار که آن را می‌نوشت، از بهجت و نشاطی تازه برخوردار بود. به همین دلیل، نام کتاب را «بهج الصباغه» گذاشت؛ یعنی بهجتی رنگارنگ در شرح نهج‌البلاغه. رحمت خدا بر او باد.\nادامه صفات اسلام را چنین بیان فرمودند:\nفَهُوَ دَعائِمُ أَساخَ فِی الْحَقِّ أَسْناخَها\nخداوند اسلام را در حق استوار کرد؛ یعنی «أَساخَ»، به‌گونه‌ای که بنیان و ریشه آن نیرومند و شکست‌ناپذیر است.\nخداوند پایه‌های محکم این بنا را با حق آمیخت. اسلام به خدا و حق وابسته است و با واقعیت و حقیقت مطابقت دارد.\nمنظور از واژه «فَهُوَ»، اسلام است؛ اما نه هر اسلامی، بلکه اسلامی که ریشه در حق دارد؛ اسلامی که دارای حلاوت، نورانیت و استحکام است، بر اجتهاد و امامت تکیه دارد و به خدا متصل است. منظور، هر نوع برداشتی از اسلام نیست.\nاسلامِ منهای امامت، اسلامی است که نورانیت آن کاسته شده و به حق متصل نیست؛ چنین اسلامی با اسلام حقیقی تفاوت دارد و نباید به اسلام آمریکایی تبدیل شود.\nوَثَبَّتَ أَساسَها\nخداوند پایه‌های اسلام را محکم کرد.\nامام صادق علیه‌السلام فرمودند:\n«بُنِی الْإِسْلامُ عَلَی الْخَمْسِ: الصَّلاةِ، وَالزَّکاةِ، وَالْحَجِّ، وَالصَّوْمِ، وَالْوِلایةِ»\nاسلام بر پنج ستون استوار شده است: نماز، زکات، حج، روزه و ولایت.\nبه‌اندازه‌ای که بر ولایت تأکید شده است، بر دیگر ستون‌ها و ارکان تأکید نشده است. ولایت، اصل و اساس است.\n«وَلا انْهِدامَ لِأَساسِهِ»\nاساس اسلام، اهل‌بیت هستند.\nوَینابِیعَ عَزُرَتْ عُیونُها\nخداوند اسلام را دارای چشمه‌هایی قرارداد که همواره پرآب‌اند و می‌جوشند و سرریز می‌شوند؛ یعنی «عَزُرَتْ». هرکس وارد آن‌ها شود، سیراب می‌شود.\nبا چشم دل، چشم عقل و از طریق ظواهر اسلام، راه برای رسیدن به حقیقت باز است.\nاسلام حوضی دارد، یعنی «حِیاضُهُ» که اهل‌بیت همواره آن را پر می‌کنند و جرعه‌جرعه آب حیات را به تشنگان این مسیر می‌نوشانند.\nوَمَصابِیحُ شُبَّتْ نِیرانُها\nاسلام چراغ‌هایی دارد که آتش آن‌ها پرفروغ و نورانی است؛ یعنی «شُبَّتْ» و نور آن‌ها سراسر عالم را فراگرفته است.\nوَمَنارُها اقْتَدی بِها سُفّارُها\nاسلام را به‌صورت منار و نشانه‌ای قرار دادند تا مسافران آن، یعنی «سُفّارُها»، با پیروی از این نشانه به مسیر درست هدایت شوند؛ یعنی «اقْتَدی».\nدر سفرهای قدیم، در طول روز کنار جاده نشانه‌هایی مانند تابلو وجود داشت و در شب، در مکان مرتفعی آتش روشن می‌کردند. به این مکان «منار» می‌گفتند تا مسیر و مقصد شناخته شود.\nاهل‌بیت، عالمان ربانی، کتاب و وجود علما، منارهای هدایت هستند تا کسی از بیراهه حرکت نکند.\nوَأَعْلامٌ قُصِدَ بِها فِجاجُها\nاسلام به پرچم‌ها و نشانه‌هایی، یعنی «أَعْلام»، آراسته شده است که به‌واسطهٔ آن‌ها مسیرهای گسترده اسلام، یعنی «فِجاجُها»، شناخته می‌شوند.\nاسلام سراسر مسیر را نشانه‌گذاری کرده است و در هر شهر و دیاری حجتی وجود دارد. حتی اگر هیچ‌کس در دسترس نباشد، خداوند، فرشتگان و اهل‌بیت از جهت معنوی می‌توانند هدایت کنند. راه برای حرکت باز است.\nوَمَناهِلُ رَوِی بِها وُرّادُها\nاسلام آبشخورهایی دارد؛ یعنی «مَناهِل». هرکس به این چشمه وارد شود، سیراب می‌شود؛ یعنی «رَوِی».\nاسلام مکتبی پویاست که فضای آن برای همه باز است. کسانی که با نیت فهم و کشف حقایق به آن روی می‌آورند، سیراب بازمی‌گردند.\nشرط سیراب‌شدن، تشنگی است. انسان باید طالب باشد؛ زیرا خداوند فیاض است و همواره فیض خود را می‌رساند. ظرف وجودی طالب نیز باید گسترده، پاک و پاکیزه باشد.\nجَعَلَ اللهُ فِیهِ مُنْتَهی رِضْوانِهِ\nاسلام دینی است که خداوند رضایت کامل خود را در آن قرار داده است.\n«رَضِیتُ لَکمُ الْإِسْلامَ دِیناً»؛ مائده، ۶.\nخداوند نهایت رضوان و خشنودی خود را در اسلام قرار داده است.\nذِرْوَةَ دَعائِمِهِ وَسَنامَ طاعَتِهِ\nخداوند برترین و مرتفع‌ترین احکام، یعنی «ذِرْوَة»، و بلندترین قله اطاعت، یعنی «سَنام»، را در اسلام قرارداد.\nاسلام، برترین ادیان است. بلندمرتبه‌ترین ستونی که باید به آن تمسک جست، اسلام است و راه‌های مخالف آن، بیراهه‌اند.\nامام باقر علیه‌السلام فرمودند که اسلام یک اصل، یک فرع و یک قله دارد. اصل آن نماز، فرع آن زکات و قله آن جهاد است. به‌واسطهٔ جهاد، نماز برپا می‌شود و اطاعت الهی در سایه قله مرتفع جهاد تحقق می‌یابد.\nفَهُوَ عِنْدَ اللهِ وَثِیقُ الْأَرْکانِ، رَفِیعُ الْبُنْیانِ\nاسلام نزد خداوند، دارای پایه‌هایی استوار و بنیانی بلندمرتبه است.\nمُنِیرُ الْبُرْهانِ، مُضِیءُ النِّیرانِ\nبرهان‌های دین اسلام روشن‌اند.\nاستدلال‌های قرآن، استدلال بر عدالت، برهان قیامت و برهان امامت بلافصل امیرالمؤمنین، از برهان‌های آشکار دین هستند. کسی نمی‌تواند خلاف آن‌ها را اثبات کند.\nعَزِیزُ السُّلْطانِ\nقدرت اسلام شکست‌ناپذیر است.\nرهبر فرمودند که نجات جوامع از همه مشکلات، در بازگشت به اسلام واقعی است.\nاسلام مایه عزت و قدرت است و به کسی که به آن عمل کند نیز عزت و قدرت می‌بخشد.\nمسلمانی که عزیز نباشد، فقط نامی از اسلام دارد. قدرت اسلام شکست‌ناپذیر است و مسلمان واقعی نیز در پرتو آن عزیز و شکست‌ناپذیر خواهد بود. او آزادگی پیدا می‌کند و از ذلت رهایی می‌یابد.\nمُشْرِفُ الْمَنارِ وَمُعَوِّزُ الْمَثارِ\nنشانه‌های اسلام، یعنی «الْمَنار»، بلندمرتبه و آشکارند.\nدگرگون‌کردن دین و برانداختن آن، امری نایاب و دشوار است؛ یعنی «مُعَوِّز». ازبین‌رفتن دین هیچ‌گاه به طور کامل محقق نمی‌شود؛ زیرا خداوند اراده کرده است که اسلام را حفظ کند.\nفَشَرِّفُوهُ، وَاتَّبِعُوهُ\nای مردم، دینی را که چنین اوصافی دارد، عزیز و گرامی بدارید. دین شریف است؛ پس آن را شریف بدانید.\nاز احکام آن پیروی کنید و از آن اطاعت کنید تا شرافت اسلام حفظ شود.\nأَدُّوا إِلَیهِ حَقَّهُ\nحق اسلام را ادا کنید. از دین طلبکار نباشید؛ شما به دین مدیون هستید. حق دین را به‌جا آورید.\nاسلام بر گردن همه ما حق دارد. ما به اسلام بدهکاریم، نه طلبکار.\nگروهی نزد پیامبر آمدند و گفتند که مسلمان شده‌اند و گویا بر پیامبر منت می‌گذاشتند. خداوند فرمود:\n«یمُنُّونَ عَلَیک أَنْ أَسْلَمُوا قُلْ لا تَمُنُّوا عَلَی إِسْلامَکمْ بَلِ اللهُ یمُنُّ عَلَیکمْ أَنْ هَداکمْ لِلْإِیمانِ إِنْ کنْتُمْ صادِقِینَ»؛ حجرات، ۱۷.\nمنت نگذارید که اسلام آورده‌اید. خداوند بر شما منت گذاشت که شما را به ایمان هدایت کرد، اگر راست‌گو باشید.\nپس شما باید حق اسلام را ادا کنید.\nوَضَعُوهُ مَواضِعَهُ\nاسلام را در همان جایگاه بلند و شایسته‌ای قرار دهید که باید در آن باشد؛ یعنی «وَضَعُوهُ».\nاسلام را وسیله‌ای برای اهداف سیاسی نکنید؛ آن را به رأی و سلیقه شخصی تفسیر نکنید؛ اسلام را خرج حزب‌ها نکنید و برای تأمین دنیای خود از آن مایه نگذارید.\nجایگاه حقیقت اسلام نباید تغییر کند. اسلام را آمریکایی و کوچه‌بازاری نکنید و شرافت و قداست آن را آلوده نسازید.\nاسلام باید عزیز و گرامی بماند.\nفرمودند: جایگاه اهل‌بیت، قرآن است و جایگاه قرآن، اهل‌بیت هستند.\nجایگاه اهل‌بیت و قرآن، قلب است و جایگاه و خانه اسلام نیز قلب است.\nمسلمان واقعی باشید.\nثُمَّ إِنَّ اللهَ سُبْحانَهُ بَعَثَ مُحَمَّداً صَلَّی اللهُ عَلَیهِ وَآلِهِ بِالْحَقِّ حِینَ دَنا مِنَ الدُّنْیا الِانْقِطاعُ\nپس از توصیف زیبای اسلام و شرافت دین، خداوند برای تبلیغ همان دین، پیامبر خاتم، حضرت محمد صلی‌الله علیه و آله، را برانگیخت؛ آن‌گاه که آشوب، خون‌ریزی ناحق، سپری‌شدن عمر دنیا و پایان آن نزدیک شده بود؛ یعنی «حِینَ دَنا».\nاینکه بعثت پیامبر با روزهای پایانی دنیا هم‌زمان دانسته شده، دو تفسیر دارد:\n۱. منظور، آخرالزمان است.\nاگر فاصله زمانی از آغاز آفرینش عالم تا بعثت پیامبر را در نظر بگیریم، دوران پایانی و امت آخر، بخش کوچکی از این بازه را تشکیل می‌دهد. هرچند این مدت میلیاردها سال باشد، در مقایسه با مجموع حیات عالم، دوران امت آخر کوتاه است. ما امت آخرالزمان هستیم؛ زیرا فاصله زمانی زیادی میان ما و دوران های پیشین وجود دارد.\nپیش از خلقت حضرت آدم علیه‌السلام نیز دوران هایی وجود داشته است.\nامام سجاد علیه‌السلام فرمودند:\n«بَلی وَاللهِ خَلَقَ اللهُ أَلْفَ أَلْفِ آدَمٍ وَأَلْفَ أَلْفِ عالَمٍ»\nآری، به خدا سوگند، خداوند هزار، هزار آدم و هزار، هزار عالم آفریده است.\nشاید نتوانیم این موضوع را اثبات یا به طور کامل درک کنیم؛ اما امام که به وحی متصل است، فرموده‌اند که پیش از حضرت آدم نیز عوالمی وجود داشته‌اند. آن عوالم آمدند و رفتند و شما آخرین امت هستید. پس منظور از پایان‌یافتن دنیا، در این تفسیر، دوران آخرالزمان است.\n۲. منظور، وضعیت مردم پیش از بعثت پیامبر است.\nپیش از بعثت پیامبر، شرایط به‌گونه‌ای بود که هر روز گویی روز پایانی زندگی مردم بود. جنگ و خون‌ریزی، بیماری، ظلم و بی‌عدالتی همیشگی بود. مردم حتی خواب و آرامش نداشتند و صبح که بیدار می‌شدند، از امنیت برخوردار نبودند.\nوَأَقْبَلَ مِنَ الْآخِرَةِ وَالِاطِّلاعِ\nگویی آخرت طلوع کرده بود. پیامبر زمانی آمد که نشانه‌های آخرت، باتوجه‌به دو تفسیر بالا، آشکار شده بود.\nوَأَظْلَمَتْ بَهْجَتُها بَعْدَ إِشْراقٍ\nخوشی‌ها و بهجت دنیا، پس از درخشندگی و نورانیت، تاریک شده بود.\nمردم گرفتار سختی‌هایی شده بودند که راهی به‌سوی رهایی پیش پایشان نمی‌گذاشت.\nپیامبران، مایه بهجت، نشاط و طراوت جامعه بودند. هنگامی که پیامبران از میان مردم رفتند، زیبایی و طراوت نیز از جامعه رخت بر بست. در دوران ششصدساله فترت و فاصله میان پیامبران، روشنایی دوران پیش از فترت به تاریکی گرایید.\nوَقامَتْ بِأَهْلِها عَلی ساقٍ\nدنیا ساق پای خود را بالا زده بود؛ یعنی مردم را به‌سختی و مشقت انداخته بود.\nانسان هنگام انجام کارهای دشوار، ساق پاهای خود را بالا می‌زند. دنیا نیز سختی و شدت خود را بر مردم تحمیل کرده بود و مردم دوران جاهلیت روی آرامش نمی‌دیدند.\nوَخَشُنَ مِنْها مِهادٌ\nبستر زندگی ناهموار شده بود و زمام امور به دست کسانی افتاده بود که مردم را به‌سختی می‌کشاندند. جنگ و شبیخون و زنده‌به‌گور کردن فرزندان، پیوسته ادامه داشت.\nوَأَزِفَ مِنْها قِیادٌ\nزمان پیوندخوردن با آخرت نزدیک شده بود.\nدنیا مردم را به یکدیگر گره‌زده بود و آنان را به‌سوی نابودی می‌برد.\nواژه «قِیاد» به طنابی اشاره دارد که با آن گله‌ای از گوسفندان را به یکدیگر می‌بندند تا گم نشوند. این واژه دو معنا دارد: معنای نخست، بستن و پیونددادن است؛ معنای دوم، انقیاد و تسلیم‌شدن.\nدنیا چنان مردم را تسلیم خودکرده بود که فکر رهایی، تغییروتحول به ذهنشان نمی‌رسید. آنان خود را مجبور به جنگ و ناآرامی می‌دانستند.\nفِی انْقِطاعِ مُدَّتِها، وَاقْتِرابِ مِنْ أَشْراطِها\nمدت دنیا روبه‌پایان بود و نشانه‌های پایان آن، یعنی «أَشْراط»، نزدیک شده بودند.\nتَصَرُّمٍ مِنْ أَهْلِها\nاهل دنیا احساس می‌کردند که پایان دنیا نزدیک است و انتظار آن را می‌کشیدند.\nوَانْفِصامٍ مِنْ حَلْقَتِها\nدنیا مانند حلقه زنجیری بود که آرام‌آرام ازهم‌گسسته می‌شد و چرخ زندگی و روزگار، یعنی «حَلْقَتِها»، به خوشی نمی‌گذشت.\nوَانْتِثارٍ بِسَبَبِها\nاسباب و عوامل زندگی ازهم‌گسسته و نظام دنیا آشفته شده بود. هرکس کار می‌کرد، به سبب ظلم، دستمزد و حق خود را دریافت نمی‌کرد و جایی برای اعتراض، شکایت، بررسی و گرفتن حق وجود نداشت.\nوَتَکشُّفٍ مِنْ عَوْراتِها\nزشتی‌های دنیا آشکار شده بود. جنگ، خون‌خواهی و ظلم افزایش‌یافته و روی خوش دنیا ازمیان‌رفته بود.\nوَقِصَرٍ مِنْ طُولِها\nعمر طولانی کوتاه شده بود.\nهمه این کلمات حضرت، شرح وضعیت جاهلیت است.\nجاهلیت، تنها یک دوره تاریخی نیست؛ بلکه یک فرهنگ و شیوه زندگی است. اینکه جاهلیت پیش از بعثت وجود داشته و اکنون به‌کلی ازمیان‌رفته است، به‌هیچ‌وجه درست نیست.\nهر روزی که انسان آرزوی مرگ کند؛ هر روزی که چرخ زندگی نچرخد؛ هر روزی که ظالم ظلم کند و حق او گرفته نشود؛ و هر روزی که کسی به مظلوم توجه نکند، آن روزگار، روزگار جاهلیت است.\nشدت و ضعف جاهلیت در جوامع مختلف متفاوت است و همه این صفات، نمادهایی از آن هستند.\nهرگاه این نمادها در جامعه‌ای دیده شوند، جاهلیت بازگشته است.\nعمر انسان باید به‌اندازه‌ای طولانی باشد که خداوند مقرر کرده است و باید با پیری و کهولت پایان یابد.\nدر خطبه ۴۰ فرمودند که جامعه باید امیر داشته باشد. امیر بد بهتر از بی امیری است؛ اما با امیر خوب و در حکومت عدل، عمرها طولانی می‌شود.\nدر حکومت ظالم، اندوه و غصه فراوان است و همین امر عمر را کوتاه می‌کند.\nأَذِقْنا حَلاوَةَ وُدِّک وَرَحْمَتِک","بخش چهارم\nمتن:\nترجمه:\nتفسیر:\nجَعَلَهُ اللَّهُ سُبْحَانَهُ بَلَاغاً لِرِسَالَتِهِ\nخدای متعال، پیامبر صلی‌الله علیه و آله را مبلغ و رسانندهٔ رسالت‌های خود قرارداد. وظیفهٔ پیامبر این بود که پیام‌های الهی را به گوش ما برساند.\nوَ کَرَامَهً لِأُمَّتِهِ\nخداوند، پیامبر را مایهٔ کرامت امت قرارداد.\nحضرت علی علیه‌السلام در مواضع مختلف نهج‌البلاغه دربارهٔ رسول خدا سخن گفته‌اند و در سه جا بر کرامت رسول‌الله تأکید می‌فرمایند:\n۱. ولادت رسول (خطبهٔ ۱)\n۲. بعثت رسول\n۳. رحلت رسول صلی‌الله علیه و آله\nکسی که ولادت، بعثت و رحلتش کریمانه است، لطفش شامل حال ما نیز می‌شود.\nوَ رَبِیعاً لِأَهْلِ زَمَانِهِ\nپیامبر، بهار زمانه است.\nبهار نماد شکوفایی است. پیامبر آمد تا ما به کمال برسیم.\nوَ رِفْعَهً لِأَعْوَانِهِ\nپیامبر، علت رفعت و سربلندی یاران خود است.\nوَ شَرَفاً لِأَنْصَارِهِ\nهرکس پیامبر را یاری کند، شرافت می‌یابد.\nتلاش و زحمت در راه پیامبر صلی‌الله علیه و آله، موجب رشد و ترقی خود انسان است. لطف پیامبر این است که هیچ‌کس را بدون پاداش نمی‌گذارد.\nصفات قرآن\nازآنجاکه قرآن قانون اساسی اسلام است، حضرت در اینجا صفاتی از قرآن را بیان می‌فرمایند که شمار آن‌ها بیش از چهل صفت است.\nأَنْزَلَ عَلَیْهِ الْکِتَابَ\nخداوند کتاب را بر او نازل کرد؛ کتابی که:\nنُوراً لَا تُطْفَأُ مَصَابِیحُهُ\nنوری است که چراغ‌های آن هرگز خاموش نمی‌شوند.\nسِرَاجاً لَا یَخْبُو تَوَقُّدُهُ\nچراغ‌راهنمای زندگی است که فروغ آن هرگز خاموش نمی‌شود و از حرکت بازنمی‌ایستد.\nبَحْراً لَا یُدْرَکُ قَعْرُهُ\nدریایی است که عمق و باطن آن شناختنی نیست. هرکس به‌اندازه‌ای از این دریا بهره می‌برد.\nوَ مِنْهَاجاً لَا یُضِلُّ نَهْجُهُ\nقرآن، راهی روشن است که هیچ‌گاه رهروان خود را به گمراهی نمی‌کشاند.\nوَ شُعَاعاً لَا یُظْلِمُ ضَوْءُهُ\nقرآن منبع نور است و پرتوهای آن هیچ‌کس را گمراه نمی‌کنند. نورانیت آن نیز در هیچ شرایطی پایان نمی‌یابد.\nوَ فُرْقَاناً لَا یَخْمَدُ بُرْهَانُهُ\nقرآن میان حق و باطل تمایز می‌گذارد و برهانی است که هرگز خاموش نمی‌شود.\nوَ تِبْیَاناً (بُنیاناً) لَا تُهْدَمُ أَرْکَانُهُ\nقرآن آشکارکنندهٔ حقایق است و حق و باطل را از یکدیگر متمایز می‌کند. همچنین بنایی استوار است که ستون‌های آن سست نمی‌شوند.\nشِفَاءً لَا تُخْشَی أَسْقَامُهُ\nقرآن شفایی است که پس از آن، از بازگشت بیماری بیمی نیست.\nامام موسی کاظم علیه‌السلام فرمودند:\nهیچ دارویی نیست مگر اینکه عضوی دیگر را بیمار می‌کند؛ تنها دارویی که شفای محض است و آثار مخرب ندارد، قرآن است.\nعِزّاً لَا تُهْزَمُ أَنْصَارُهُ\nقرآن مایهٔ عزت است و یاران و پشتیبانان آن نیز عزیزند؛ هیچ قدرتی نمی‌تواند بر آنان غلبه کند.\nحَقّاً لَا تُخْذَلُ أَعْوَانُهُ\nقرآن به حق متصل است و یاران و پشتیبانان آن هرگز خوار و ذلیل نمی‌شوند.\nفَهُوَ مَعْدِنُ الْإِیمَانِ وَ بُحْبُوحَتُهُ\nاصل ایمان در قرآن است.\nکسی که خواهان پیشرفت در ایمان است، باید قرآن را بخواند؛ همان قرآنی که اوصافش بیان شد.\nیَنَابِیعُ الْعِلْمِ و بحوره\nقرآن، چشمه‌سار علم است و دریاهای دانش در آن جای دارند. هیچ عالمی نمی‌تواند ادعا کند که همهٔ قرآن را به طور کامل فراگرفته است؛ زیرا قرآن برای هر فرد، حرف و نکته‌ای تازه دارد.\nرِیَاضُ الْعَدْلِ وَ غُدْرَانُهُ\nقرآن، باغ عدالت است و برکه‌های عدالت [غُدارتُه] نیز در آن قرار دارند.\nدر مقدمهٔ کتاب «البیان فی تفسیرالقرآن»، اثر آیت‌الله ابوالقاسم خویی که دربارهٔ اعجاز قرآن است، چند صفت قرآن، مانند پیشگویی، اعجاز و...، ذکر شده است که یکی از آن‌ها اعتدال قرآن است. آیات مختلفی در این زمینه وجود دارد؛ از جمله:\nسورهٔ مبارکهٔ نساء، آیهٔ ۵۸:\n«إِنَّ اللَّهَ یَأمُرُکُم أَن تُؤَدُّوا الأَماناتِ إِلیٰ أَهلِها…»\nسورهٔ نحل، آیهٔ ۹۰:\n«إِنَّ اللَّهَ یَأمُرُ بِالعَدلِ وَالإِحسانِ»\nآیهٔ ۲۹ سورهٔ اسراء:\n«لا تَجْعَلْ یَدَکَ مَغْلُولَهً إِلی عُنُقِکَ وَ لا تَبْسُطْها کُلَّ …»\nآیهٔ ۱۹۲ سورهٔ بقره:\n«فَمَنِ اعْتَدَی عَلَیْکُمْ فَاعْتَدُوا عَلَیْهِ بِمِثْلِ مَا اعْتَدَی عَلَیْکُمْ …»\nآیهٔ ۸۵ سورهٔ هود:\n«وَلَا تَبْخَسُوا النَّاسَ أَشْیَاءَهُمْ وَلَا تَعْثَوْا فِی الْأَرْضِ …»\nأَثَافِیُّ الْإِسْلَامِ وَ بُنْیَانُهُ\nقرآن، ستون و پایهٔ اسلام [اَثاقیّ] است و بنیان اسلام بر قرآن استوار است.\nوَ أَوْدِیَهُ الْحَقِّ وَ غِیطَانُهُ\nصحرای وسیع [اَودیه] و کشتزار حق در قرآن قرار دارند. قرآن برای انسان‌های مستعد، وسیلهٔ نجات و صعود است؛ به‌شرط آنکه کشتزار وجود آنان آمادگی داشته باشد. استعداد را باید کسب کرد.\nطبق آیهٔ ۳۰ سورهٔ روم:\n«فِطْرَتَ اللَّهِ الَّتِی فَطَرَ النَّاسَ عَلَیْهَا ۚ لَا تَبْدِیلَ لِخَلْقِ اللَّه»\nهمهٔ انسان‌ها فطرت خداجویی دارند و باید این فطرت ارزشمند را حفظ کنند.\nوَ بَحْرٌ لَا یَنْزِفُهُ الْمُسْتَنْزِفُونَ\nقرآن دریایی است که هرقدر برداشت‌کنندگان [مُستنزِف] از معارف و تفسیر آن بهره ببرند، پایان نمی‌یابد [لایَنزفُه].\nوَ عُیُونٌ لَا یَنْضِبُهَا الْمَاتِحُونَ\nقرآن چشمه‌ساری است که آبکشان [ماتِح] هرقدر از آن آب بیرون بکشند، آب آن کم نمی‌شود [لا یَنضب]. قرآن برای همه حرفی تازه دارد؛ هنگامی که با طهارت به سراغ آن بروند، معارف و نکات جدیدی دریافت می‌کنند.\nوَ مَنَاهِلُ لَا یَغِیضُهَا الْوَارِدُونَ\nقرآن چشمه‌ها و آبشخورهایی دارد که با ورود افراد به آن‌ها، آبشان کم نمی‌شود [لایَغیضُ]. هرچه انس با قرآن بیشتر شود، معارف دریافتی نیز افزایش می‌یابد.\nمَنَازِلُ لَا یَضِلُّ نَهْجَهَا الْمُسَافِرُونَ\nقرآن منزلگاهی است که مسیر آن [نَهَجها] پیچ‌وخم ندارد تا مسافران راه را گم کنند؛ مسیر آن برای همگان روشن و مستقیم است.\nآیهٔ ۸۲ سورهٔ اسراء:\nوَنُنَزِّلُ مِنَ الْقُرْآنِ مَا هُوَ شِفَاءٌ وَرَحْمَةٌ لِلْمُؤْمِنِینَ وَلَا یزِیدُ الظَّالِمِینَ إِلَّا خَسَارًا.\nوَأَعْلَامٌ لَا یَعْمَی عَنْهَا السَّائِرُونَ\nاین جاده نشانه‌هایی دارد که از چشم رهروان آن پنهان نمی‌مانند؛ رهروانی که از شرایط کنونی خود ناراضی‌اند و تصمیم دارند رشد کنند.\nامکان ندارد کسی برای هدایت به سراغ قرآن برود و قرآن چیزی به او نیاموزد.\nوَ آکَامٌ لَا یَجُوزُ عَنْهَا الْقَاصِدُونَ\nقرآن تپه‌ای مرتفع [آکامُُ] است که جویندگان نمی‌توانند از آن عبور کنند [لایَجوز]. هرچه پیش بروند، باز هم به قلهٔ آن نمی‌رسند.\nجَعَلَهُ اللَّهُ رِیّاً لِعَطَشِ الْعُلَمَاءِ\nخداوند قرآن را وسیلهٔ سیراب‌شدن [رَیّاً] عطش عالمان قرارداد.\nتا انسان دلش معنویت را نخواهد و طالب آن نباشد، چیزی به او نمی‌دهند.\nحکمت ۴۵۷: دو گروه هیچ‌گاه سیراب نمی‌شوند:\n۱. طالب علم\n۲. طالب دنیا\nوَ رَبِیعاً لِقُلُوبِ الْفُقَهَاءِ\nکسی که با جدیت در قرآن جست‌وجو کند، قرآن بهار قلب اوست. حضرت دربارهٔ پیامبر صلی‌الله علیه و آله نیز فرمودند که ایشان بهار زمانه هستند.\nقرآن و پیامبر صلی‌الله علیه و آله از یکدیگر جداشدنی نیستند.\nوَ مَحَاجَّ لِطُرُقِ الصُّلَحَاءِ\nقرآن، راهی روشن [محاج] برای انسان‌های صالح است.\nوَ دَوَاءً لَیْسَ بَعْدَهُ دَاءٌ\nقرآن دارویی است که پس از آن، بیماری [داءُ] وجود ندارد و به داروی دیگری نیاز نیست.\nهمهٔ این‌ها به یک شرط است: عمل به قرآن. حفظ‌کردن الفاظ قرآن خوب است، اما مهم‌تر از آن، رعایت احکام قرآن در موقعیت‌های مختلف زندگی است.\nروایتی از امام باقر علیه‌السلام:\nحضرت باقر علیه‌السلام فرمودند: قاریان قرآن سه گروه‌اند:\nالف) کسی که قرآن می‌خواند و آن را سرمایهٔ کسب خود قرار می‌دهد، به‌وسیلهٔ آن از پادشاهان مستمری می‌طلبد و بر مردم بزرگی می‌فروشد.\nب) کسی که قرآن می‌خواند و حروف آن را حفظ می‌کند، اما احکام و حدود آن را ضایع می‌گرداند.\nج) مردی که قرآن می‌خواند، داروی قرآن را بر دل دردمندش می‌نهد، با آن شب‌زنده‌داری می‌کند، روزش را با تشنگی به پایان می‌رساند، هنگام نمازها و در مساجد به آن قیام می‌کند و به احترام آن از بستر خواب خود دوری می‌جوید.\nخداوند به‌وسیلهٔ آنان بلا را برطرف می‌کند، به برکت وجودشان خداوند عزوجل شر دشمنان را بازمی‌دارد و به برکت آنان از آسمان باران نازل می‌کند. به خدا سوگند، این افراد در میان قرآن‌خوانان از کبریت احمر کمیاب‌ترند.\nوَ نُوراً لَیْسَ مَعَهُ ظُلْمَهٌ\nقرآن نوری است که هیچ ظلمتی با آن همراه نیست.\nوَ حَبْلًا وَثِیقاً عُرْوَتُهُ\nقرآن طنابی است که گره‌های آن استوار و محکم‌اند. نجات از چاه دنیا با چنگ‌زدن به این گره‌ها امکان‌پذیر است.\nوَ مَعْقِلًا مَنِیعاً ذِرْوَتُهُ\nقرآن پناهگاهی [معقِل] استوار است که قلهٔ آن [ذروتُه] بلند و دست‌نیافتنی است.\nو عزا لِمَنْ تَوَلَّاهُ\nقرآن برای کسی که آن را سرپرست امور خود قرار دهد و هر کاری را با اجازه و راهنمایی قرآن انجام دهد، مایهٔ عزت است.\nوَ سِلْماً لِمَنْ دَخَلَهُ\nقرآن، پناهگاه و مایهٔ آرامش و امنیت کسی است که وارد قلعهٔ آن شود؛ چنین فردی در امنیت نگه داشته می‌شود.\nهُدًی لِمَنِ ائْتَمَّ بِهِ\nقرآن برای کسی که به آن اعتماد کند و از آن پیروی کند [اِئتَمَ]، مایهٔ هدایت است.\nوَ عُذْراً لِمَنِ انْتَحَلَهُ\nقرآن، وسیلهٔ پذیرش عذر کسی است که آن را به‌عنوان دین و آیین خود بپذیرد [نِحله].\nوَ لِمَنْ تَکَلَّمَ بِهِ\nکسی که با قرآن سخن بگوید و سخنی استوار و مستحکم بر پایهٔ آن بیان کند، هیچ‌کس نمی‌تواند او را شکست دهد.\nشَاهِداً لِمَنْ خَاصَمَ بِهِ\nاگر کسی در بحثی علمی با دیگری به مخاصمه بپردازد و به قرآن استشهاد کند، قرآن سخن او را تأیید می‌کند.\nوَ فَلْجاً لِمَنْ حَاجَّ بِهِ\nقرآن باعث پیروزی [فلجاً] کسی است که با آن احتجاج کند.\nاهل‌بیت علیهم‌السلام در پاسخ به شبهات، افراد را به قرآن ارجاع می‌دادند.\nوَ حَامِلًا لِمَنْ حَمَلَهُ\nکسی که قرآن را حمل کند؛ یعنی احکام آن را بر دوش بگیرد و به آن عمل کند، از سوی قرآن نیز یاری می‌شود و قرآن او را به مقصدی که باید برسد، می‌رساند.\nپیامبر صلی‌الله علیه و آله فرمودند: ای کسانی که قرآن را تلاوت می‌کنید، تقواپیشه کنید. من مسئول رساندن قرآن به شما مردم هستم و شما مسئولید که به قرآن عمل کنید. چرا به شیوه‌ای که قرآن مشخص کرده است، عمل نکردید؟\nوَ مَطِیَّهً لِمَنْ أَعْمَلَهُ\nقرآن می‌تواند وسیلهٔ سیروسلوک و مرکبی راهوار [مطیه] برای کسی باشد که به آن عمل می‌کند.\nآیَهً لِمَنْ تَوَسَّمَ\nقرآن، مدال و نشان کسی است که خود را با قرآن نشانه‌گذاری [تَوَسم] کرده است.\nوَ جُنَّهً لِمَنِ اسْتَلْأَمَ\nقرآن سپر کسی است که آن را بپوشد؛ یعنی لباس زیور تقوا را از قرآن به دست آورد و بر تن کند.\nوَ عِلْماً لِمَنْ وَعَی\nقرآن برای کسی که معارف آن را درک و حفظ کند [وَعی]، مایهٔ دانش است.\nحَدِیثاً لِمَنْ رَوَی\nقرآن برای کسی که آن را روایت کند [رَوی’]، کلامی ارزشمند است.\nوَ حُکْماً لِمَنْ قَضَی\nقرآن برای کسی که بر اساس آن حکم کند [قضی]، معیاری برای صدور حکم درست است.\nدر خطبهٔ ۱۵۸، حضرت فرمودند: این قرآن در برابر دیدگان شماست؛ قرآن را به سخن درآورید. اما قرآن با هیچ‌یک از شما سخن نمی‌گوید؛ من مفسر قرآن هستم.\nنهج‌البلاغه، شرح قرآن است.\nکسی که قرآن را سرپرست امور خود قرار دهد و همان‌طور که پیش‌تر گفته شد، همهٔ کارهای خود را با اجازه و راهنمایی قرآن انجام دهد، این صفات قرآن شامل حال او خواهد شد."]});
